CREATE OR REPLACE PROCEDURE miglab.pr_recalculate_claim ( p_claim_id claim.claim_id%TYPE ) AS $body$
DECLARE

    ora2pg_rowcount int;
l_billed  numeric;
    l_allowed numeric;
    l_message varchar(4000);

BEGIN

    SELECT coalesce(SUM(billed_amount),0),
           coalesce(SUM(allowed_amount),0)
    INTO STRICT l_billed,
         l_allowed
    FROM claim_detail
    WHERE claim_id = p_claim_id;

    UPDATE claim
       SET total_billed  = l_billed,
           total_allowed = l_allowed,
           claim_status  =
               CASE
                   WHEN claim_status = 'NEW'
                   THEN 'PROCESSING'
                   ELSE claim_status
               END
     WHERE claim_id = p_claim_id;

    GET DIAGNOSTICS ora2pg_rowcount = ROW_COUNT;
IF ora2pg_rowcount = 0 THEN
        RAISE EXCEPTION '%', 'Claim ID ' || p_claim_id || ' does not exist'
         USING ERRCODE = '45001';
    END IF;

    l_message := 'Claim recalculated successfully';

    INSERT INTO migration_audit(
        audit_id,
        process_name,
        source_count,
        target_count,
        status,
        message,
        created_timestamp
    )
    VALUES (
        nextval('seq_migration_audit'),
        'PR_RECALCULATE_CLAIM',
        1,
        1,
        'SUCCESS',
        l_message,
        statement_timestamp()
    );

EXCEPTION
    WHEN OTHERS THEN

        l_message := SUBSTR(SQLERRM,1,4000);

        INSERT INTO migration_audit(
            audit_id,
            process_name,
            source_count,
            target_count,
            status,
            message,
            created_timestamp
        )
        VALUES (
            nextval('seq_migration_audit'),
            'PR_RECALCULATE_CLAIM',
            1,
            0,
            'FAILED',
            l_message,
            statement_timestamp()
        );

        RAISE;
END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
